mapper.select:
SELECT MEM_USED       AS memUsedRate,
       END_TIME       AS collectDate
FROM HOUR_MEMORY
WHERE ASSET_ID = #{assetId}
  AND END_TIME >= #{day}
ORDER BY collectDate DESC

SELECT SWAP_USED_RATE AS swapUsedRate,
       END_TIME       AS collectDate
FROM HOUR_MEMORY
WHERE ASSET_ID = #{assetId}
  AND END_TIME >= #{day}
ORDER BY collectDate DESC
